package com.xuhang.mealops.inventory.application;
import java.math.*; import java.time.LocalDate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.xuhang.mealops.ingredient.application.IngredientRepository; import com.xuhang.mealops.inventory.domain.*; import com.xuhang.mealops.measurement.domain.*;
@Service public class InventoryConsumptionApplicationService { private final InventoryBatchRepository batches; private final InventoryTransactionRepository transactions; private final IngredientRepository ingredients; public InventoryConsumptionApplicationService(InventoryBatchRepository b,InventoryTransactionRepository t,IngredientRepository i){batches=b;transactions=t;ingredients=i;} @Transactional public ConsumptionResult consume(long ingredientId,BigDecimal amount,String code){Unit u=Unit.fromCode(code).orElseThrow(()->new InvalidInventoryBatchException("Unknown unit")); Quantity q=Quantity.of(amount,u).convertTo(u.baseUnit()); if(ingredients.findById(ingredientId).isEmpty()) throw new com.xuhang.mealops.ingredient.application.IngredientNotFoundException(ingredientId); var plan=new InventoryConsumptionAllocator().allocate(ingredientId,q,batches.findConsumableBatches(ingredientId,u.baseUnit())); for(var a:plan.allocations()) if(!batches.consumeWithVersion(a.batchId(),a.amount(),a.expectedVersion(),a.unit())) throw new InventoryConcurrentModificationException(); long id=transactions.createConsumption(ingredientId,q.amount(),q.unit().code(),plan.allocations()); return new ConsumptionResult(id,ingredientId,q,plan.allocations()); } public record ConsumptionResult(long transactionId,long ingredientId,Quantity quantity,java.util.List<InventoryConsumptionAllocation> allocations){} }
